// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller 'from', the callee address 'callee', and arrays _tos and v
    function testFuzz_property(address from, address callee, address[] memory _tos, uint[] memory v) public {
        // admissible domain: _tos must be non-empty to satisfy the require in transfer
        if (_tos.length == 0) return;
        // ensure v has at least as many entries as _tos to avoid out-of-bounds in the loop
        if (v.length < _tos.length) return;

        // Because transfer performs low-level .call on the provided callee address, and a naked EOA
        // will accept calls (succeeding with empty return), we don't need a special adversary here.
        // Call transfer and capture whether it returns true via try/catch and returned bool.

        bool ok;
        try c.transfer(from, callee, _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // If it reverts, treat as failure (shouldn't for non-empty _tos in reference)
            ok = false;
        }

        // The universal property: for any admissible input (non-empty _tos and matching v length),
        // the reference implementation always returns true. The mutant that returns false will
        // cause this assertion to fail for some inputs. We assert that the call returned true.
        assertTrue(ok);
    }
}

