pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address callee, address[] memory _tos, uint256[] memory v) public {
        // admissible domain: _tos must be non-empty and lengths must match
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Deploy a minimal helper that accepts any call so that low-level call succeeds (EOAs would also succeed,
        // but using a contract ensures deterministic behavior regardless of fuzzed callee address)
        // If the fuzzer passes the helper's address as callee, that's OK; otherwise we still call the fuzzed callee.
        Helper h = new Helper();

        address target = callee;
        // allow either the provided callee or our helper to be used; if the provided callee is the zero address use helper
        if (target == address(0)) target = address(h);

        // Call transfer and observe its returned boolean via try/catch to get the return value
        bool ok;
        try c.transfer(from, target, _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // should not revert for admissible inputs in reference; mark as failure
            ok = false;
        }

        // The reference implementation guarantees the return is true for every admissible input
        assertTrue(ok);
    }
}

contract Helper {
    // Accept any call and return true-sized empty data so low-level call from C succeeds
    fallback() external payable {
        // do nothing
    }
}

