// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: a caller address (sender) and two arrays of the same length > 0
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        // admissible domain: _tos must be non-empty and lengths must match
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        // The external callee address must be a contract for the low-level call to be exercisable.
        // Deploy a benign callee that simply accepts the call and returns.
        // We still fuzz caddress parameter but will pass an actual deployed contract address to C.transfer,
        // because a fuzzed EOA would make the low-level call a no-op success; deploying a contract keeps behavior realistic.
        Callee callee = new Callee();

        // call C.transfer and capture its returned boolean by using try/catch on an external low-level call
        bool ok;
        try c.transfer(from, address(callee), _tos, v) returns (bool retval) {
            ok = retval;
        } catch {
            ok = false; // if it reverts, treat as false
        }

        // The reference contract always returns true for any non-empty _tos (admissible domain).
        // Single assertion: must be true for all admissible inputs on the reference; the mutant (which returns false)
        // will violate this for some inputs and thus the test fails when run against the mutant.
        assertTrue(ok);
    }
}

// Minimal benign callee that accepts any call and returns (does nothing).
contract Callee {
    fallback() external payable returns (bytes memory) {
        return "";
    }
}

