    C c;
    function setUp() public { c = new C(); }

    // fuzzed inputs: an arbitrary address 'from', an array of target addresses '_tos', and array of values 'v'
    function testFuzz_property(address from, address[] calldata _tos, uint[] calldata v) public {
        // admissible domain: _tos must be non-empty and lengths must match for a sensible call
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        // The property: calling transfer with non-empty _tos should return true for the reference C.
        // We capture the boolean return using try/catch to allow comparing completion as well.
        bool ok;
        try c.transfer(from, address(0), _tos, v) returns (bool ret) {
            // record completion and returned boolean
            ok = ret;
        } catch {
            ok = false; // treat revert as false
        }

        // The universal property the reference satisfies: ok must be true for all admissible inputs
        assertTrue(ok);
    }
}
